import { defineEval } from "eve/evals";

// The documenting-d2e-features skill covers adding feature docs to the d2e
// docs website (docs/website, Docusaurus, autogenerated sidebar). A "document
// the feature I just implemented" ask should load it — not the d2e overview
// skill, and not a testing skill.
export default defineEval({
  description: "loads the documenting-d2e-features skill for a document-the-feature task",
  async test(t) {
    await t.send(
      "I just implemented a new cohort-comparison feature in Data2Evidence (d2e). Add the documentation for it to the d2e documentation website.",
    );
    t.succeeded();
    t.loadedSkill("documenting-d2e-features");
  },
});
